{
  "extracted_concepts": [
    {
      "name": "随机变量的数字特征",
      "aliases": ["numerical characteristics of random variables", "数字特征"],
      "definition_snippet": "对分布的简化描述，包括期望、方差、协方差等。",
      "category": "concept"
    },
    {
      "name": "数学期望",
      "aliases": ["mathematical expectation", "期望"],
      "definition_snippet": "离散型为Σxₖpₖ，连续型为∫xf(x)dx。",
      "category": "operation"
    },
    {
      "name": "离散型",
      "aliases": ["discrete type", "离散型随机变量"],
      "definition_snippet": "离散型随机变量的期望为E(X)=Σxₖpₖ。",
      "category": "concept"
    },
    {
      "name": "连续型",
      "aliases": ["continuous type", "连续型随机变量"],
      "definition_snippet": "连续型随机变量的期望为E(X)=∫xf(x)dx。",
      "category": "concept"
    },
    {
      "name": "随机变量函数的期望",
      "aliases": ["expectation of function of random variable", "E(g(X))"],
      "definition_snippet": "E(g(X))=Σg(xₖ)pₖ或∫g(x)f(x)dx。",
      "category": "operation"
    },
    {
      "name": "期望的性质",
      "aliases": ["properties of expectation", "期望性质"],
      "definition_snippet": "包括E(C)=C、线性性、独立时E(XY)=E(X)E(Y)。",
      "category": "property"
    },
    {
      "name": "期望的线性性",
      "aliases": ["linearity of expectation", "E(aX+b)=aE(X)+b"],
      "definition_snippet": "E(aX+b)=aE(X)+b，E(X+Y)=E(X)+E(Y)。",
      "category": "property"
    },
    {
      "name": "独立随机变量乘积的期望",
      "aliases": ["expectation of product of independent variables", "E(XY)=E(X)E(Y)"],
      "definition_snippet": "X、Y独立时，E(XY)=E(X)E(Y)。",
      "category": "theorem"
    },
    {
      "name": "方差",
      "aliases": ["variance", "D(X)"],
      "definition_snippet": "D(X)=E[(X-E(X))²]=E(X²)-[E(X)]²。",
      "category": "concept"
    },
    {
      "name": "标准差",
      "aliases": ["standard deviation", "σ"],
      "definition_snippet": "σ=√D(X)。",
      "category": "concept"
    },
    {
      "name": "方差的性质",
      "aliases": ["properties of variance", "方差性质"],
      "definition_snippet": "D(C)=0，D(aX+b)=a²D(X)，独立时和差方差相加。",
      "category": "property"
    },
    {
      "name": "常见分布的期望和方差",
      "aliases": ["expectations and variances of common distributions", "常见分布数字特征"],
      "definition_snippet": "给出二项、泊松、均匀、指数、正态分布的期望和方差。",
      "category": "concept"
    },
    {
      "name": "二项分布",
      "aliases": ["binomial distribution", "B(n,p)"],
      "definition_snippet": "X~B(n,p)时，E(X)=np，D(X)=np(1-p)。",
      "category": "concept"
    },
    {
      "name": "泊松分布",
      "aliases": ["Poisson distribution", "P(λ)"],
      "definition_snippet": "X~P(λ)时，E(X)=λ，D(X)=λ。",
      "category": "concept"
    },
    {
      "name": "均匀分布",
      "aliases": ["uniform distribution", "U(a,b)"],
      "definition_snippet": "X~U(a,b)时，E(X)=(a+b)/2，D(X)=(b-a)²/12。",
      "category": "concept"
    },
    {
      "name": "指数分布",
      "aliases": ["exponential distribution", "E(λ)"],
      "definition_snippet": "X~E(λ)时，E(X)=1/λ，D(X)=1/λ²。",
      "category": "concept"
    },
    {
      "name": "正态分布",
      "aliases": ["normal distribution", "N(μ,σ²)"],
      "definition_snippet": "X~N(μ,σ²)时，E(X)=μ，D(X)=σ²。",
      "category": "concept"
    },
    {
      "name": "协方差",
      "aliases": ["covariance", "Cov(X,Y)"],
      "definition_snippet": "Cov(X,Y)=E(XY)-E(X)E(Y)。",
      "category": "concept"
    },
    {
      "name": "相关系数",
      "aliases": ["correlation coefficient", "ρ_XY"],
      "definition_snippet": "ρ=Cov(X,Y)/(√D(X)√D(Y))，且|ρ|≤1。",
      "category": "concept"
    },
    {
      "name": "不相关",
      "aliases": ["uncorrelated", "ρ=0"],
      "definition_snippet": "ρ=0称X与Y不相关。",
      "category": "concept"
    },
    {
      "name": "独立",
      "aliases": ["independence", "independent"],
      "definition_snippet": "独立时E(XY)=E(X)E(Y)，且D(X±Y)=D(X)+D(Y)。",
      "category": "concept"
    },
    {
      "name": "原点矩",
      "aliases": ["raw moment", "E(X^k)"],
      "definition_snippet": "E(X^k)称为X的k阶原点矩。",
      "category": "concept"
    },
    {
      "name": "中心矩",
      "aliases": ["central moment", "E[(X-E(X))^k]"],
      "definition_snippet": "E[(X-E(X))^k]称为k阶中心矩。",
      "category": "concept"
    },
    {
      "name": "数字特征与分布的关系",
      "aliases": ["relation between numerical characteristics and distribution", "数字特征作用"],
      "definition_snippet": "期望描述中心位置，方差描述离散程度，协方差描述线性关联。",
      "category": "concept"
    },
    {
      "name": "分布律",
      "aliases": ["probability mass", "p_k"],
      "definition_snippet": "离散型期望求和中的概率pₖ。",
      "category": "concept"
    }
  ],
